/// An icon: its cache key and its SVG source.
pub struct Icon {
    pub key: &'static str,
    pub svg: &'static str,
}

/// The check inside a task box.
pub const CHECKMARK: Icon = Icon {
    key: "live-editor/check.svg",
    svg: CHECK,
};

/// The arrow after an external link.
pub const LINK_OUT: Icon = Icon {
    key: "live-editor/external-link.svg",
    svg: EXTERNAL_LINK,
};

/// The cross on a removable item.
pub const CROSS: Icon = Icon {
    key: "live-editor/x.svg",
    svg: X,
};

/// A table's add buttons.
pub const ADD: Icon = Icon {
    key: "live-editor/plus.svg",
    svg: PLUS,
};

/// A rendered diagram's edit button.
pub const EDIT_SOURCE: Icon = Icon {
    key: "live-editor/code-xml.svg",
    svg: CODE_XML,
};

/// A callout title's or property's icon.
pub fn glyph(glyph: Glyph) -> Icon {
    let (key, svg) = match glyph {
        Glyph::Pencil => ("live-editor/pencil.svg", PENCIL),
        Glyph::ClipboardList => ("live-editor/clipboard-list.svg", CLIPBOARD_LIST),
        Glyph::Info => ("live-editor/info.svg", INFO),
        Glyph::CircleCheck => ("live-editor/circle-check.svg", CIRCLE_CHECK),
        Glyph::Flame => ("live-editor/flame.svg", FLAME),
        Glyph::Check => ("live-editor/check.svg", CHECK),
        Glyph::CircleHelp => ("live-editor/circle-help.svg", CIRCLE_HELP),
        Glyph::TriangleAlert => ("live-editor/triangle-alert.svg", TRIANGLE_ALERT),
        Glyph::X => ("live-editor/x.svg", X),
        Glyph::Zap => ("live-editor/zap.svg", ZAP),
        Glyph::Bug => ("live-editor/bug.svg", BUG),
        Glyph::List => ("live-editor/list.svg", LIST),
        Glyph::Quote => ("live-editor/quote.svg", QUOTE),
        Glyph::Text => ("live-editor/text.svg", TEXT),
        Glyph::Binary => ("live-editor/binary.svg", BINARY),
        Glyph::SquareCheck => ("live-editor/square-check.svg", SQUARE_CHECK),
        Glyph::Calendar => ("live-editor/calendar.svg", CALENDAR),
        Glyph::Clock => ("live-editor/clock.svg", CLOCK),
        Glyph::Tags => ("live-editor/tags.svg", TAGS),
        Glyph::Forward => ("live-editor/forward.svg", FORWARD),
        Glyph::Plus => ("live-editor/plus.svg", PLUS),
    };
    Icon { key, svg }
}
